// ==========================================
// --- MAIN APPLICATION ROOT (ROUTER & STATE) ---
// ==========================================
function App() {
  const [view, setViewState] = useState('home'); // 'home' | 'overview' | 'feature1' | 'feature2' | 'feature3' | 'feature4' | 'feature5' | 'feature6' | 'feature7' | 'feature8' | 'feature9'
  const [feature1Screen, setFeature1Screen] = useState(1);
  const [teleconsultScreen, setTeleconsultScreen] = useState('entry'); // 'entry' | 'booking' | 'queue' | 'call' | 'doctor' | 'summary'
  const [actorRole, setActorRole] = useState('worker'); // 'worker' | 'patient' | 'doctor' | 'shop_owner' | 'lab_staff' | 'facility' | 'admin'
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);

  // Feature 01 States
  const [patient, setPatient] = useState(INITIAL_PATIENT);
  const [symptoms, setSymptoms] = useState(INITIAL_SYMPTOMS);
  const [redFlags, setRedFlags] = useState(INITIAL_RED_FLAGS);
  const [triageResult, setTriageResult] = useState(null);
  const [facilities, setFacilities] = useState(MOCK_FACILITIES);
  const [selectedFacility, setSelectedFacility] = useState(MOCK_FACILITIES[0]);

  // Feature 02 States
  const [teleconsultAppointment, setTeleconsultAppointment] = useState(null);
  const [recordedVitals, setRecordedVitals] = useState([]);
  const [consultationDocumentation, setConsultationDocumentation] = useState(null);

  const parseHash = () => {
    const hash = window.location.hash || '#home';
    if (hash === '#overview' || hash === '#features') {
      setViewState('overview');
    } else if (hash.startsWith('#screen=')) {
      const num = Number(hash.replace('#screen=', '')) || 1;
      setViewState('feature1');
      setFeature1Screen(num);
    } else if (hash.startsWith('#teleconsult=')) {
      const screenName = hash.replace('#teleconsult=', '') || 'entry';
      setViewState('feature2');
      setTeleconsultScreen(screenName);
    } else if (hash === '#feature1') {
      setViewState('feature1');
    } else if (hash === '#feature2') {
      setViewState('feature2');
    } else if (hash === '#feature3' || hash === '#referrals' || hash === '#referrals-doctor' || hash === '#referrals-worker' || hash === '#referrals-facility' || hash === '#referrals-patient') {
      setViewState('feature3');
    } else if (hash === '#feature4' || hash === '#followups' || hash === '#followups-doctor' || hash === '#followups-worker' || hash === '#followups-facility' || hash === '#followups-patient') {
      setViewState('feature4');
    } else if (hash === '#feature5' || hash === '#records' || hash === '#records-patient' || hash === '#records-doctor' || hash === '#records-worker') {
      setViewState('feature5');
    } else if (hash === '#feature6' || hash === '#medicine' || hash === '#diagnostic' || hash === '#shop-owner' || hash === '#lab-staff' || hash === '#doctor-orders' || hash === '#diagnostic-orders') {
      setViewState('feature6');
    } else if (
      hash === '#feature7' ||
      hash === '#dashboard' ||
      hash === '#facility-dashboard' ||
      hash === '#dashboard-overview' ||
      hash === '#dashboard-care' ||
      hash === '#dashboard-queue' ||
      hash === '#dashboard-resources' ||
      hash === '#dashboard-analytics' ||
      hash === '#dashboard-alerts'
    ) {
      setViewState('feature7');
    } else if (
      hash === '#feature9' ||
      hash === '#command-center' ||
      hash === '#district-admin' ||
      hash === '#command'
    ) {
      setViewState('feature9');
    } else if (
      hash === '#feature8' ||
      hash === '#schemes' ||
      hash === '#scheme-finder' ||
      hash === '#govt-schemes'
    ) {
      setViewState('feature8');
    } else if (hash === '#about' || hash === '#about-us') {
      setViewState('about');
    } else {
      setViewState('home');
    }
  };

  useEffect(() => {
    parseHash();
    const onHashChange = () => parseHash();
    window.addEventListener('hashchange', onHashChange);
    return () => window.removeEventListener('hashchange', onHashChange);
  }, []);

  const updateHash = (newHash) => {
    if (window.location.hash === newHash) return;
    
    // Coalesce sequential programmatic navigations to avoid duplicate browser history entries
    if (window.navigatingHash) {
      window.history.replaceState(null, '', newHash);
    } else {
      window.location.hash = newHash;
      window.navigatingHash = true;
      setTimeout(() => {
        window.navigatingHash = false;
      }, 50);
    }
  };

  const [viewHistory, setViewHistory] = useState(['overview']);

  const navigateToView = (v) => {
    setViewHistory((prev) => {
      if (prev[prev.length - 1] === v) return prev;
      return [...prev, v];
    });
    setViewState(v);
  };

  const setView = (v) => {
    navigateToView(v);
    updateHash('#' + v);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleBackFromReferrals = () => {
    // Find previously visited feature in the workflow (ignoring current view and avoiding jumping to home)
    const historyWithoutCurrent = viewHistory.filter((h) => h !== 'feature3');
    const lastVisitedFeature = [...historyWithoutCurrent].reverse().find((h) => h !== 'home');

    if (lastVisitedFeature) {
      if (lastVisitedFeature === 'feature1') {
        setView('feature1');
        setScreen(9);
      } else if (lastVisitedFeature === 'feature2') {
        setView('feature2');
        setTeleconsultScreen('entry');
      } else {
        setView(lastVisitedFeature);
      }
    } else {
      // Natural single step back in Features Suite workflow:
      // Module 03 (Smart Referrals) -> Module 02 (Teleconsult & Queue)
      setView('feature2');
      setTeleconsultScreen('entry');
    }
  };

  const setScreen = (s) => {
    setFeature1Screen(s);
    updateHash('#screen=' + s);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleRestartFeature1 = () => {
    setPatient(INITIAL_PATIENT);
    setSymptoms(INITIAL_SYMPTOMS);
    setRedFlags(INITIAL_RED_FLAGS);
    setTriageResult(null);
    setScreen(1);
  };

  const handleRestartFeature2 = () => {
    setTeleconsultAppointment(null);
    setRecordedVitals([]);
    setConsultationDocumentation(null);
    setTeleconsultScreen('entry');
  };

  const isFeatureView = [
    'overview',
    'feature1',
    'feature2',
    'feature3',
    'feature4',
    'feature5',
    'feature6',
    'feature7',
    'feature8',
    'feature9'
  ].includes(view);

  return (
    <div className="min-h-screen flex flex-col bg-white text-slate-900">
      <Header
        currentView={view}
        setView={setView}
        currentScreen={feature1Screen}
        setScreen={setScreen}
        actorRole={actorRole}
        setActorRole={setActorRole}
      />

      {/* HOMEPAGE VIEW */}
      {view === 'home' && (
        <main className="flex-1 max-w-6xl xl:max-w-7xl w-full mx-auto p-4 sm:p-6 md:p-8">
          <ScreenHomepage
            onLaunchFeature1={() => {
              setView('feature1');
              setScreen(1);
            }}
            onLaunchFeature2={() => {
              setView('feature2');
              setTeleconsultScreen('entry');
            }}
            onLaunchFeature3={() => {
              setView('feature3');
            }}
            onLaunchFeature4={() => {
              setView('feature4');
            }}
            onLaunchFeature5={() => {
              setView('feature5');
            }}
            onLaunchFeature6={() => {
              setView('feature6');
            }}
            onLaunchFeature7={() => {
              setView('feature7');
            }}
            onLaunchFeature8={() => {
              setView('feature8');
            }}
            onLaunchFeature9={() => {
              setView('feature9');
            }}
            onLaunchAbout={() => {
              setView('about');
            }}
            actorRole={actorRole}
            setActorRole={setActorRole}
          />
        </main>
      )}

      {/* ABOUT US PAGE */}
      {view === 'about' && (
        <main className="flex-1 max-w-6xl xl:max-w-7xl w-full mx-auto p-4 sm:p-6 md:p-8">
          <ScreenAboutUs
            onBackToHome={() => setView('home')}
            onLaunchFeature1={() => {
              setView('feature1');
              setScreen(1);
            }}
            onLaunchFeature2={() => {
              setView('feature2');
              setTeleconsultScreen('entry');
            }}
            onLaunchFeature3={() => {
              setView('feature3');
            }}
            onLaunchFeature4={() => {
              setView('feature4');
            }}
            onLaunchFeature5={() => {
              setView('feature5');
            }}
            onLaunchFeature6={() => {
              setView('feature6');
            }}
            onLaunchFeature7={() => {
              setView('feature7');
            }}
            onLaunchFeature8={() => {
              setView('feature8');
            }}
            onLaunchFeature9={() => {
              setView('feature9');
            }}
          />
        </main>
      )}

      {/* FEATURES SUITE WORKSPACE (Side Navbar + Active Feature Screen) */}
      {isFeatureView && (
        <div className="flex-1 flex flex-col md:flex-row w-full bg-slate-50 min-h-[calc(100vh-65px)]">
          <FeaturesSideNavbar
            currentView={view}
            setView={setView}
            setScreen={setScreen}
            setTeleconsultScreen={setTeleconsultScreen}
            actorRole={actorRole}
            setActorRole={setActorRole}
            collapsed={sidebarCollapsed}
            onToggleCollapse={() => setSidebarCollapsed(!sidebarCollapsed)}
          />

          <main className="flex-1 min-w-0 bg-white md:border-l border-slate-200 overflow-y-auto">
            {/* VIEW: OVERVIEW */}
            {view === 'overview' && (
              <ScreenOverview
                actorRole={actorRole}
                setActorRole={setActorRole}
                setView={setView}
                setScreen={setScreen}
                setTeleconsultScreen={setTeleconsultScreen}
              />
            )}

            {/* VIEW 2: FEATURE 01 — SMART CARE NAVIGATOR */}
        {view === 'feature1' && (
          <div>
            {feature1Screen === 1 && (
              <Screen1PatientInfo
                patient={patient}
                setPatient={setPatient}
                onNext={() => setScreen(2)}
              />
            )}

            {feature1Screen === 2 && (
              <Screen2SymptomAssessment
                symptoms={symptoms}
                setSymptoms={setSymptoms}
                onNext={() => setScreen(3)}
                onBack={() => setScreen(1)}
              />
            )}

            {feature1Screen === 3 && (
              <Screen3RedFlags
                redFlags={redFlags}
                setRedFlags={setRedFlags}
                onNext={() => setScreen(4)}
                onBack={() => setScreen(2)}
              />
            )}

            {feature1Screen === 4 && (
              <Screen4TriageProcessing
                patient={patient}
                symptoms={symptoms}
                redFlags={redFlags}
                onComplete={(data) => {
                  if (data) setTriageResult(data);
                  setScreen(5);
                }}
              />
            )}

            {feature1Screen === 5 && (
              <Screen5TriageResult
                triage={triageResult}
                onFindHospitals={() => setScreen(6)}
                onBack={() => setScreen(3)}
              />
            )}

            {feature1Screen === 6 && (
              <Screen6HospitalSearch
                location={patient.location}
                latitude={patient.latitude}
                longitude={patient.longitude}
                requiredSpecialty={triageResult?.requiredSpecialty}
                emergencyRequired={triageResult?.emergencyRequired}
                onComplete={(liveFacilities) => {
                  if (liveFacilities && liveFacilities.length > 0) {
                    setFacilities(liveFacilities);
                    setSelectedFacility(liveFacilities[0]);
                  }
                  setScreen(7);
                }}
              />
            )}

            {feature1Screen === 7 && (
              <Screen7RecommendedFacilities
                facilities={facilities}
                onSelectFacility={(fac) => {
                  setSelectedFacility(fac);
                  setScreen(8);
                }}
                onBack={() => setScreen(5)}
              />
            )}

            {feature1Screen === 8 && (
              <Screen8FacilityDetails
                facility={selectedFacility}
                onNext={() => setScreen(9)}
                onBack={() => setScreen(7)}
              />
            )}

            {feature1Screen === 9 && (
              <Screen9ReferralPass
                facility={selectedFacility}
                patient={patient}
                onRestart={handleRestartFeature1}
              />
            )}
          </div>
        )}

        {/* VIEW 3: FEATURE 02 — TELECONSULTATION & QUEUE MANAGEMENT */}
        {view === 'feature2' && (
          <div>
            {teleconsultScreen === 'entry' && (
              <ScreenTeleconsultEntry
                actorRole={actorRole}
                onSelectPath={(path) => {
                  setActorRole(path);
                  setTeleconsultScreen('booking');
                }}
                onBackToHome={() => setView('home')}
              />
            )}

            {teleconsultScreen === 'booking' && (
              <ScreenTeleconsultBooking
                pathActor={actorRole}
                onBookSuccess={(apt) => {
                  setTeleconsultAppointment(apt);
                  setTeleconsultScreen('queue');
                }}
                onBack={() => setTeleconsultScreen('entry')}
                onEmergencyEscalate={() => {
                  setView('feature1');
                  setScreen(1);
                }}
              />
            )}

            {teleconsultScreen === 'queue' && (
              <ScreenTeleconsultQueue
                appointment={teleconsultAppointment}
                onJoinCall={() => setTeleconsultScreen('call')}
                onBack={() => setTeleconsultScreen('booking')}
              />
            )}

            {teleconsultScreen === 'call' && (
              <ScreenTeleconsultCall
                appointment={teleconsultAppointment}
                pathActor={actorRole}
                onCompleteConsultation={(vitalsLogged) => {
                  setRecordedVitals(vitalsLogged);
                  setTeleconsultScreen('doctor');
                }}
              />
            )}

            {teleconsultScreen === 'doctor' && (
              <ScreenDoctorDocumentation
                appointment={teleconsultAppointment}
                vitals={recordedVitals}
                onSaveDocumentation={(docData) => {
                  setConsultationDocumentation(docData);
                  setTeleconsultScreen('summary');
                }}
              />
            )}

            {teleconsultScreen === 'summary' && (
              <ScreenConsultationSummary
                consultationData={consultationDocumentation}
                onRestart={handleRestartFeature2}
                onGoHome={() => setView('home')}
              />
            )}
          </div>
        )}

        {/* VIEW 4: FEATURE 03 — SMART REFERRAL MANAGEMENT SYSTEM */}
        {view === 'feature3' && (
          <ScreenReferralManagement
            actorRole={actorRole}
            setActorRole={setActorRole}
            onBack={handleBackFromReferrals}
            onBackToHome={() => setView('home')}
            onNavigateToCareNavigator={() => {
              setView('feature1');
              setScreen(1);
            }}
          />
        )}

        {/* VIEW 5: FEATURE 04 — HIGH-RISK PATIENT FOLLOW-UP SYSTEM */}
        {view === 'feature4' && (
          <ScreenHighRiskFollowUp
            actorRole={actorRole}
            setActorRole={setActorRole}
            onBackToHome={() => setView('home')}
            onNavigateToCareNavigator={() => {
              setView('feature1');
              setScreen(1);
            }}
            onNavigateToReferrals={() => setView('feature3')}
          />
        )}

        {/* VIEW 6: FEATURE 05 — INTEROPERABLE HEALTH RECORDS */}
        {view === 'feature5' && (
          <ScreenInteroperableRecords
            actorRole={actorRole}
            setActorRole={setActorRole}
            onBackToHome={() => setView('home')}
            onNavigateToCareNavigator={() => {
              setView('feature1');
              setScreen(1);
            }}
            onNavigateToTeleconsult={() => {
              setView('feature2');
              setTeleconsultScreen('entry');
            }}
            onNavigateToReferrals={() => setView('feature3')}
            onNavigateToFollowUps={() => setView('feature4')}
          />
        )}

        {/* VIEW 7: FEATURE 06 — MEDICINE AVAILABILITY & DIAGNOSTIC COORDINATION */}
        {view === 'feature6' && (
          <ScreenMedicineDiagnostics
            actorRole={actorRole}
            setActorRole={setActorRole}
            onBackToHome={() => setView('home')}
            onNavigateToCareNavigator={() => {
              setView('feature1');
              setScreen(1);
            }}
            onNavigateToTeleconsult={() => {
              setView('feature2');
              setTeleconsultScreen('entry');
            }}
            onNavigateToReferrals={() => setView('feature3')}
            onNavigateToFollowUps={() => setView('feature4')}
            onNavigateToRecords={() => setView('feature5')}
          />
        )}

        {/* VIEW 8: FEATURE 07 — FACILITY DASHBOARD & MULTI-SOURCE AGGREGATION LAYER */}
        {view === 'feature7' && (
          <ScreenFacilityDashboard
            actorRole={actorRole}
            setActorRole={setActorRole}
            onBackToHome={() => setView('home')}
            onNavigateToCareNavigator={() => {
              setView('feature1');
              setScreen(1);
            }}
            onNavigateToTeleconsult={() => {
              setView('feature2');
              setTeleconsultScreen('entry');
            }}
            onNavigateToReferrals={() => setView('feature3')}
            onNavigateToFollowUps={() => setView('feature4')}
            onNavigateToRecords={() => setView('feature5')}
            onNavigateToMedicine={() => setView('feature6')}
          />
        )}

                {/* VIEW 9: FEATURE 08 — AI GOVERNMENT HEALTH SCHEME FINDER */}
        {view === 'feature8' && (
          <ScreenSchemeFinder
            actorRole={actorRole}
            setActorRole={setActorRole}
            onBackToHome={() => setView('home')}
            onNavigateToCareNavigator={() => {
              setView('feature1');
              setScreen(1);
            }}
            onNavigateToTeleconsult={() => {
              setView('feature2');
              setTeleconsultScreen('entry');
            }}
            onNavigateToReferrals={() => setView('feature3')}
            onNavigateToRecords={() => setView('feature5')}
            triageContext={triageResult}
            patientContext={patient}
          />
        )}

        {/* VIEW 10: FEATURE 09 — DISTRICT ADMIN COMMAND CENTER (MV-DAC) */}
        {view === 'feature9' && (
          <ScreenCommandCenter
            actorRole={actorRole}
            setActorRole={setActorRole}
            onBackToHome={() => setView('home')}
            onNavigateToFacilityDashboard={() => setView('feature7')}
            onNavigateToSchemeFinder={() => setView('feature8')}
          />
        )}
      </main>
    </div>
  )}

      {/* HOMEPAGE ONLY: Pre-Footer Interactive Beats Banner */}
      {view === 'home' && (
        <HomepageBeatsBanner
          onLaunchFeature1={() => {
            setView('feature1');
            setScreen(1);
          }}
          onLaunchFeature2={() => {
            setView('feature2');
            setTeleconsultScreen('entry');
          }}
          onLaunchFeature8={() => {
            setView('feature8');
          }}
        />
      )}

      <Footer
        setView={setView}
        setScreen={setScreen}
        setTeleconsultScreen={setTeleconsultScreen}
        setActorRole={setActorRole}
      />
    </div>
  );
}

// Mount the React Application
const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<App />);

